const startDeliveryAttempt = `-- name: StartDeliveryAttempt :one
UPDATE delivery SET status = 'in_flight', attempts = attempts + 1
WHERE delivery.id = $1
  AND ((delivery.status = 'pending' AND (delivery.next_attempt_at IS NULL OR delivery.next_attempt_at <= $2::bigint))
       OR delivery.status = 'in_flight')
  AND NOT EXISTS (
    SELECT 1 FROM lease
    WHERE lease.name = 'delivery:' || delivery.id AND lease.expires_at > $2::bigint
      AND lease.holder <> $3::text
  )
RETURNING id, event_id, subscription_id, status, attempts, next_attempt_at, last_error, held_until, hold_started_at, hold_watch_cooldown_ms, hold_prerelease, hold_watch_id, hold_raw, hold_input, traceparent, replay_base_attempts
`

type StartDeliveryAttemptParams struct {
	ID     string
	Now    int64
	Holder string
}

// Every lease of a delivery counts as an attempt, so an attempt cut short by
// a crash counts too. Unlike SQLite's, the update repeats the due predicate
// of ListLeasableDueDeliveries (ADR 0028 §3): writers that take no lease lock
// (FailPendingDeliveries, FailHeldDelivery, CancelHeldDeliveries) may have
// changed or deleted the row since it was selected; then no row comes back
// and the caller skips it. The holder's own new lease does not count.
func (q *Queries) StartDeliveryAttempt(ctx context.Context, arg StartDeliveryAttemptParams) (Delivery, error) {
	row := q.db.QueryRowContext(ctx, startDeliveryAttempt, arg.ID, arg.Now, arg.Holder)
	var i Delivery
	err := row.Scan(
		&i.ID,
		&i.EventID,
		&i.SubscriptionID,
		&i.Status,
		&i.Attempts,
		&i.NextAttemptAt,
		&i.LastError,
		&i.HeldUntil,
		&i.HoldStartedAt,
		&i.HoldWatchCooldownMs,
		&i.HoldPrerelease,
		&i.HoldWatchID,
		&i.HoldRaw,
		&i.HoldInput,
		&i.Traceparent,
		&i.ReplayBaseAttempts,
	)
	return i, err
}

